"use client";

import { useCallback, useMemo, useState } from "react";
import Link from "next/link";
import { StudioVoicePicker } from "@/components/studio-voice-picker";
import type { CharacterProfile } from "@/types/character-profile";
import {
  isStudioAutoGeneratedImageSource,
  isStudioGeneratedImageSource,
  type ImageSource,
} from "@/types/studio-json";
import type { StudioImageSearchSource } from "../types";
import { resolveStudioImageSettingsVisibility } from "../studio-image-settings-visibility";
import type { StudioVoiceOption } from "../use-studio-bootstrap-data";
import { getTypecastVoiceCatalogId } from "../studio-manual-voice-options";

const TYPECAST_SPEED_OPTIONS = Array.from({ length: 16 }, (_, index) => (0.5 + index * 0.1).toFixed(1));

type StudioAdvancedSettingsPanelProps = {
  sectionScope?: "all" | "voice" | "image";
  imageSource: ImageSource;
  imageSearchSource: StudioImageSearchSource;
  defaultTtsProvider: "typecast";
  debugImageSearch: boolean;
  scriptMode: "normal" | "dialogue";
  selectedVoiceId: string;
  selectedQuoteVoiceId: string;
  selectedMaleVoiceId: string;
  selectedFemaleVoiceId: string;
  selectedTypecastEmotionType: string;
  selectedTypecastSpeed: string;
  selectedVoiceOption: StudioVoiceOption | null;
  voiceOptions: StudioVoiceOption[];
  voicePreviewLoading: boolean;
  voicePreviewPlaying: boolean;
  fixedCharacterProfilesHref?: string;
  templateManagerHref?: string;
  fixedCharacterProfiles?: CharacterProfile[];
  fixedCharacterProfileId?: string;
  disabled?: boolean;
  onImageSourceChangeAction: (value: ImageSource) => void;
  onImageSearchSourceChangeAction: (value: StudioImageSearchSource) => void;
  onDebugImageSearchChangeAction: (checked: boolean) => void;
  onFixedCharacterProfileIdChangeAction: (value: string) => void;
  onScriptModeChangeAction: (value: "normal" | "dialogue") => void;
  onTypecastEmotionTypeChangeAction: (value: string) => void;
  onTypecastSpeedChangeAction: (value: string) => void;
  onVoiceChangeAction: (value: string) => void;
  onQuoteVoiceChangeAction: (value: string) => void;
  onMaleVoiceChangeAction: (value: string) => void;
  onFemaleVoiceChangeAction: (value: string) => void;
  onAddCustomTypecastVoiceAction: (value: string) => void;
  onPreviewVoiceAction: () => void;
  onStopVoicePreviewAction: () => void;
};

export function StudioAdvancedSettingsPanel({
  sectionScope = "all",
  imageSource,
  imageSearchSource,
  defaultTtsProvider,
  debugImageSearch,
  scriptMode,
  selectedVoiceId,
  selectedQuoteVoiceId,
  selectedMaleVoiceId,
  selectedFemaleVoiceId,
  selectedTypecastEmotionType,
  selectedTypecastSpeed,
  selectedVoiceOption,
  voiceOptions,
  voicePreviewLoading,
  voicePreviewPlaying,
  fixedCharacterProfilesHref,
  templateManagerHref,
  fixedCharacterProfiles = [],
  fixedCharacterProfileId = "",
  disabled = false,
  onImageSourceChangeAction,
  onImageSearchSourceChangeAction,
  onDebugImageSearchChangeAction,
  onFixedCharacterProfileIdChangeAction,
  onScriptModeChangeAction,
  onTypecastEmotionTypeChangeAction,
  onTypecastSpeedChangeAction,
  onVoiceChangeAction,
  onQuoteVoiceChangeAction,
  onMaleVoiceChangeAction,
  onFemaleVoiceChangeAction,
  onAddCustomTypecastVoiceAction,
  onPreviewVoiceAction,
  onStopVoicePreviewAction,
}: StudioAdvancedSettingsPanelProps) {
  const imageSourceId = "studio-image-source";
  const fixedCharacterProfileIdSelect = "studio-fixed-character-profile";
  const imageSearchSourceId = "studio-image-search-source";
  const debugImageSearchId = "studio-image-debug";
  const voiceId = "studio-voice-select";
  const quoteVoiceId = "studio-dialogue-quote-voice";
  const maleVoiceId = "studio-dialogue-male-voice";
  const femaleVoiceId = "studio-dialogue-female-voice";
  const typecastEmotionId = "studio-typecast-emotion";
  const typecastSpeedId = "studio-typecast-speed";
  const customTypecastVoiceId = "studio-typecast-custom-voice-id";
  const singleVoiceModeId = "studio-voice-mode-single";
  const dialogueVoiceModeId = "studio-voice-mode-dialogue";
  const safeSelectedVoiceId = selectedVoiceId.trim();
  const [customTypecastVoiceInput, setCustomTypecastVoiceInput] = useState("");
  const [customTypecastVoiceNotice, setCustomTypecastVoiceNotice] = useState("");
  const selectedVoiceIsTypecast =
    safeSelectedVoiceId.length > 0
      ? selectedVoiceOption?.provider === "typecast" ||
        safeSelectedVoiceId.startsWith("typecast:voice:") ||
        safeSelectedVoiceId.startsWith("tc_")
      : defaultTtsProvider === "typecast";
  const showVoiceSettings = sectionScope !== "image";
  const showImageSettings = sectionScope !== "voice";

  const handleAddCustomTypecastVoice = useCallback(() => {
    const voiceId = getTypecastVoiceCatalogId(customTypecastVoiceInput);
    if (!voiceId) {
      setCustomTypecastVoiceNotice("추가할 Typecast voice id를 입력해 주세요.");
      return;
    }
    onAddCustomTypecastVoiceAction(customTypecastVoiceInput);
    setCustomTypecastVoiceInput("");
    setCustomTypecastVoiceNotice(`${voiceId} 음성을 목록에 추가했습니다.`);
  }, [customTypecastVoiceInput, onAddCustomTypecastVoiceAction]);
  const isAutoGeneratedImageMode = isStudioAutoGeneratedImageSource(imageSource);
  const isPromptImageMode = isStudioGeneratedImageSource(imageSource);
  const selectedFixedCharacterProfile = useMemo(
    () => fixedCharacterProfiles.find((profile) => profile.characterId === fixedCharacterProfileId),
    [fixedCharacterProfileId, fixedCharacterProfiles]
  );
  const imageSettingsVisibility = resolveStudioImageSettingsVisibility(
    imageSource,
    Boolean(selectedFixedCharacterProfile)
  );

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "var(--space-3)" }}>
      {showVoiceSettings ? (
      <fieldset
        disabled={disabled}
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "var(--space-2)",
          padding: 0,
          margin: 0,
          border: "none",
          minInlineSize: 0,
        }}
      >
        <div className="studio-advanced-typecast-field">
          <div style={{ fontWeight: 600, fontSize: "0.875rem" }}>음성 방식</div>
          <div className="studio-advanced-voice-mode-row" role="radiogroup" aria-label="음성 방식">
            <button
              id={singleVoiceModeId}
              type="button"
              className={`studio-advanced-voice-mode-btn${scriptMode === "normal" ? " is-active" : ""}`}
              aria-pressed={scriptMode === "normal"}
              onClick={() => onScriptModeChangeAction("normal")}
              disabled={disabled}
            >
              단일 나레이션
            </button>
            <button
              id={dialogueVoiceModeId}
              type="button"
              className={`studio-advanced-voice-mode-btn${scriptMode === "dialogue" ? " is-active" : ""}`}
              aria-pressed={scriptMode === "dialogue"}
              onClick={() => onScriptModeChangeAction("dialogue")}
              disabled={disabled}
            >
              대화형/화자별
            </button>
          </div>
          <p className="studio-advanced-voice-id-help">
            여기서는 제작 방향만 정합니다. 화자가 여러 명이면 JSON 생성 후 화자별 매핑에서 실제 음성을 확정합니다.
          </p>
        </div>

        <label htmlFor={voiceId} style={{ fontWeight: 600, fontSize: "0.875rem" }}>나레이션 음성</label>
        <div className="studio-advanced-voice-row">
          <StudioVoicePicker
            id={voiceId}
            value={selectedVoiceId}
            options={voiceOptions}
            emptyLabel="기본 음성"
            className="studio-advanced-voice-select"
            disabled={disabled}
            onChangeAction={onVoiceChangeAction}
          />
          <button type="button" className="btn-secondary" onClick={onPreviewVoiceAction} disabled={disabled || voicePreviewLoading}>
            {voicePreviewLoading ? "재생 준비 중..." : "음성 미리듣기"}
          </button>
          <button type="button" className="btn-secondary" onClick={onStopVoicePreviewAction} disabled={disabled || (!voicePreviewLoading && !voicePreviewPlaying)}>
            미리듣기 중단
          </button>
        </div>
        <div className="studio-advanced-typecast-field">
          <label htmlFor={customTypecastVoiceId} className="studio-label-sm">Typecast voice id 직접 추가</label>
          <div className="studio-advanced-voice-id-row">
            <input
              id={customTypecastVoiceId}
              className="input-field"
              type="text"
              value={customTypecastVoiceInput}
              onChange={(event) => {
                setCustomTypecastVoiceInput(event.target.value);
                if (customTypecastVoiceNotice) setCustomTypecastVoiceNotice("");
              }}
              onKeyDown={(event) => {
                if (event.key === "Enter") {
                  event.preventDefault();
                  handleAddCustomTypecastVoice();
                }
              }}
              placeholder="예: tc_6059dad0b83880769a50502f"
              disabled={disabled}
            />
            <button type="button" className="btn-secondary" onClick={handleAddCustomTypecastVoice} disabled={disabled}>
              voice id 추가
            </button>
          </div>
          <p className="studio-advanced-voice-id-help">
            Typecast 카탈로그에 없는 커스텀 음성도 `voice id`만 알면 바로 선택 목록에 넣을 수 있습니다. `tc_...` 또는 `typecast:voice:tc_...` 둘 다 입력할 수 있습니다.
          </p>
          {customTypecastVoiceNotice ? <p className="studio-advanced-voice-id-notice">{customTypecastVoiceNotice}</p> : null}
        </div>
        <div style={{ fontSize: "0.75rem", color: "var(--text-secondary)" }}>
          단일 나레이션에서는 전체 기본 음성으로, 대화형/화자별에서는 화자 매핑 전 예비 나레이션 음성으로 사용합니다.
        </div>
        <details open={scriptMode === "dialogue"}>
          <summary style={{ cursor: "pointer", fontWeight: 600, fontSize: "0.9rem" }}>화자별 기본값</summary>
          <div style={{ display: "flex", flexDirection: "column", gap: "var(--space-3)", marginTop: "var(--space-3)" }}>
        <div className="studio-advanced-typecast-field">
          <label htmlFor={quoteVoiceId} className="studio-label-sm">대사 기본 음성</label>
          <StudioVoicePicker
            id={quoteVoiceId}
            value={selectedQuoteVoiceId}
            options={voiceOptions}
            emptyLabel="나레이션과 동일"
            disabled={disabled}
            onChangeAction={onQuoteVoiceChangeAction}
          />
          <p className="studio-tts-field-help">
            성별을 특정할 수 없는 화자와 별도 지정이 없는 대사 화자 기본값입니다.
          </p>
        </div>
        <div className="studio-advanced-typecast-field">
          <label htmlFor={maleVoiceId} className="studio-label-sm">남자 화자 기본 음성</label>
          <StudioVoicePicker
            id={maleVoiceId}
            value={selectedMaleVoiceId}
            options={voiceOptions}
            emptyLabel="대사 기본 음성 사용"
            disabled={disabled}
            onChangeAction={onMaleVoiceChangeAction}
          />
        </div>
        <div className="studio-advanced-typecast-field">
          <label htmlFor={femaleVoiceId} className="studio-label-sm">여자 화자 기본 음성</label>
          <StudioVoicePicker
            id={femaleVoiceId}
            value={selectedFemaleVoiceId}
            options={voiceOptions}
            emptyLabel="대사 기본 음성 사용"
            disabled={disabled}
            onChangeAction={onFemaleVoiceChangeAction}
          />
          <p className="studio-tts-field-help">
            자동 화자 분리가 `male_1`, `female_1`, `unknown_1` 같은 ID를 만들면 여기 기본값을 먼저 적용하고, JSON 패널의 화자별 매핑이 있으면 그 값이 우선합니다.
          </p>
        </div>
          </div>
        </details>
        {selectedVoiceIsTypecast ? (
          <>
            <div className="studio-advanced-typecast-field">
              <label htmlFor={typecastEmotionId} className="studio-label-sm">Typecast 감정</label>
              <input
                id={typecastEmotionId}
                className="input-field"
                type="text"
                value={selectedTypecastEmotionType}
                onChange={(event) => onTypecastEmotionTypeChangeAction(event.target.value)}
                placeholder="비워두면 설정된 기본 감정 사용"
                disabled={disabled}
              />
              <p className="studio-tts-field-help">
                메인 TTS 선택에 적용할 감정입니다. 비워두면 보이스 자산 값 또는 설정 탭 기본 감정을 그대로 사용합니다.
              </p>
            </div>
            <div className="studio-advanced-typecast-field">
              <label htmlFor={typecastSpeedId} className="studio-label-sm">음성 배속</label>
              <select
                id={typecastSpeedId}
                className="input-field"
                value={selectedTypecastSpeed}
                onChange={(event) => onTypecastSpeedChangeAction(event.target.value)}
                disabled={disabled}
              >
                <option value="">기본 속도 사용</option>
                {TYPECAST_SPEED_OPTIONS.map((value) => (
                  <option key={value} value={value}>
                    {value}x
                  </option>
                ))}
              </select>
              <p className="studio-tts-field-help">
                Typecast 합성 속도입니다. 비워두면 env 또는 설정 탭의 기본 속도를 그대로 사용합니다.
              </p>
            </div>
          </>
        ) : null}
      </fieldset>
      ) : null}

      {showImageSettings ? (
      <details open={sectionScope === "image" || undefined}>
        <summary style={{ cursor: "pointer", fontWeight: 600, fontSize: "0.95rem" }}>
          {sectionScope === "image" ? "이미지 준비 설정" : "고급 제작 설정"}
        </summary>
        <fieldset
          disabled={disabled}
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "var(--space-3)",
            marginTop: "var(--space-3)",
            padding: 0,
            marginInline: 0,
            border: "none",
            minInlineSize: 0,
          }}
        >
        <div className="studio-advanced-typecast-field">
          <label htmlFor={imageSourceId} className="studio-label-sm">이미지 준비 방식</label>
          <select
            id={imageSourceId}
            className="input-field"
            value={imageSource}
            onChange={(event) => onImageSourceChangeAction(event.target.value as ImageSource)}
            disabled={disabled}
          >
            <option value="crawl-only">크롤링 이미지</option>
            <option value="manual-ai-prompt">AI 이미지(수동 생성)</option>
            <option value="auto-ai-generate">AI 이미지(자동 생성)</option>
          </select>
          <p className="studio-tts-field-help">
            {isAutoGeneratedImageMode
              ? "프롬프트를 준비한 뒤 실제 이미지 후보까지 자동으로 생성합니다."
              : imageSource === "manual-ai-prompt"
                ? "장면별 프롬프트만 준비합니다. 이미지는 외부에서 직접 만든 뒤 URL·파일·내 자산으로 적용합니다."
                : "대본과 관련된 이미지를 자동으로 찾아 슬라이드별 후보로 준비합니다."}
          </p>
        </div>

        {imageSettingsVisibility.showFixedCharacterSelection ? (
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: "0.75rem",
              padding: "0.95rem 1rem",
              borderRadius: 18,
              background: "#f8fafc",
              border: "1px solid rgba(15,23,42,0.08)",
            }}
          >
            <label htmlFor={fixedCharacterProfileIdSelect} className="studio-label-sm">
              고정 캐릭터
            </label>
            <select
              id={fixedCharacterProfileIdSelect}
              className="input-field"
              value={selectedFixedCharacterProfile?.characterId || ""}
              onChange={(event) => onFixedCharacterProfileIdChangeAction(event.target.value)}
              disabled={disabled}
            >
              <option value="">선택 안 함</option>
              {fixedCharacterProfiles.map((profile) => (
                <option key={profile.characterId} value={profile.characterId}>
                  {profile.displayName || profile.characterId}
                </option>
              ))}
            </select>
            <p className="studio-tts-field-help">
              {selectedFixedCharacterProfile
                ? `${selectedFixedCharacterProfile.displayName || selectedFixedCharacterProfile.characterId} 외형을 모든 장면에 공통 적용합니다.`
                : fixedCharacterProfiles.length > 0
                  ? "선택하지 않으면 스타일과 대본을 기준으로 장면 인물을 설계합니다."
                  : "저장된 고정 캐릭터가 없습니다. 선택 없이 진행하거나 프로필에서 추가할 수 있습니다."}
            </p>
            {selectedFixedCharacterProfile?.anchorImageUrl ? (
              <img
                src={selectedFixedCharacterProfile.anchorImageUrl}
                alt={`${selectedFixedCharacterProfile.displayName || selectedFixedCharacterProfile.characterId} 기준 이미지`}
                style={{ width: 96, height: 96, objectFit: "cover", borderRadius: 14 }}
              />
            ) : null}
            {fixedCharacterProfilesHref ? (
              <div>
                <Link href={fixedCharacterProfilesHref} className="btn-secondary">
                  {fixedCharacterProfiles.length > 0 ? "프로필 캐릭터 편집" : "고정 캐릭터 추가"}
                </Link>
              </div>
            ) : null}
          </div>
        ) : null}

        {imageSource === "crawl-only" ? (
        <div className="studio-advanced-typecast-field">
          <label htmlFor={imageSearchSourceId} className="studio-label-sm">크롤링 세부 방식</label>
          <select
            id={imageSearchSourceId}
            className="input-field"
            value={imageSearchSource}
            onChange={(event) => onImageSearchSourceChangeAction(event.target.value as StudioImageSearchSource)}
            disabled={disabled}
          >
            <option value="crawl">크롤링 이미지 사용</option>
            <option value="library">저장소 이미지 사용</option>
          </select>
          <div className="studio-tts-field-help">
            `크롤링 이미지 사용`은 Giphy와 Naver에서 그대로 찾고, `저장소 이미지 사용`은 Giphy 저장소를 먼저 본 뒤 없으면 Giphy에서 추가로 찾습니다. 일반 컷은 계속 Naver에서 크롤링합니다.
          </div>
        </div>
        ) : null}

        {isPromptImageMode ? null : (
          <p className="studio-tts-field-help">
            이미지 provider와 검색 query는 대본을 읽고 슬라이드마다 자동으로 판단합니다.
          </p>
        )}

        {imageSource === "crawl-only" ? (
        <div style={{ display: "flex", flexDirection: "column", gap: "var(--space-2)" }}>
          <div style={{ fontWeight: 600, fontSize: "0.875rem" }}>이미지 검색 디버그</div>
          <label htmlFor={debugImageSearchId} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: "0.875rem" }}>
            <input
              id={debugImageSearchId}
              type="checkbox"
              checked={debugImageSearch}
              onChange={(event) => onDebugImageSearchChangeAction(event.target.checked)}
              disabled={disabled}
            />
            GIPHY 선택 이유와 실패 사유 표시
          </label>
          <div style={{ fontSize: "0.75rem", color: "var(--text-secondary)" }}>
            켜면 미리보기 warnings에 `query`, 선택된 provider, fallback 순서, 탈락 사유가 함께 표시되어 어떤 영어 쿼리와 결과가 채택됐는지 바로 확인할 수 있습니다.
          </div>
        </div>
        ) : null}
        </fieldset>
      </details>
      ) : null}
    </div>
  );
}
